using System;

// PROGRAM: Eksperimen Penanganan Exception dan Keyword 'throw'
public class AccountService
{
    public static void TarikTunai(decimal saldo, decimal nominal)
    {
        if (nominal <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(nominal), "Nominal penarikan harus lebih besar dari 0.");
        }

        if (saldo < nominal)
        {
            // Melempar exception domain spesifik
            throw new InvalidOperationException($"Saldo tidak cukup! Saldo: Rp {saldo:N0}, Penarikan: Rp {nominal:N0}");
        }

        Console.WriteLine($"Penarikan berhasil: Rp {nominal:N0}");
    }
}

public class Program
{
    public static void Main()
    {
        try
        {
            Console.WriteLine("Mencoba penarikan melebihi saldo...");
            AccountService.TarikTunai(100_000m, 500_000m);
        }
        catch (InvalidOperationException ex) when (ex.Message.Contains("Saldo tidak cukup"))
        {
            // Exception filter berhasil menangkap kondisi spesifik
            Console.WriteLine($"[TERTANGKAP DENGAN FILTER] {ex.Message}");
        }
        finally
        {
            // Selalu dieksekusi dalam kondisi apa pun
            Console.WriteLine("[FINALLY] Audit logging siklus penarikan ditutup.");
        }
    }
}

