using System;

public class PaymentProcessor
{
    public static string ProcessPaymentSafe(decimal saldo, decimal amount)
    {
        try
        {
            if (amount <= 0)
                throw new ArgumentException("Amount must be positive.");

            if (saldo < amount)
                throw new InvalidOperationException("Insufficient balance.");

            return "[SUCCESS: Payment completed]";
        }
        catch (Exception ex) when (ex is ArgumentException or InvalidOperationException)
        {
            return $"[ERROR: {ex.Message}]";
        }
    }

    public static void Main()
    {
        Console.WriteLine(ProcessPaymentSafe(100000m, 50000m));
        Console.WriteLine(ProcessPaymentSafe(100000m, 200000m));
    }
}
